27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "address_line1")
43	    private String addressLine1;
44	
45	    @Column(name = "address_line2")
46	    private String addressLine2;
47	
48	    @Column(name = "city")
49	    @NotEmpty
50	    private String city;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
55	    private String telephone;
56	
57	    @Column(name = "email")
58	    private String email;
59	
60	    @Column(name = "postcode")
61	    private String postcode;
62	
63	    @Column(name = "registration_date", columnDefinition = "DATE")
64	    private LocalDate registrationDate;
65	
66	    @Column(name = "birth_date", columnDefinition = "DATE")
67	    private LocalDate birthDate;
68	
69	    @Column(name = "customer_code")
70	    private String customerCode;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Column(name = "household_size")
76	    private Integer householdSize;
77	
78	    @Column(name = "bulk_signup_warning")
79	    private Boolean bulkSignupWarning;
80	
81	    @Column(name = "possible_duplicate")
82	    private Boolean possibleDuplicate;
83	
84	    @Column(name = "possible_duplicate_of")
85	    private Integer possibleDuplicateOf;
86	
87	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
88	    private Set<Pet> pets;
89	
90	    public String getAddress() {
91	        return this.address;
92	    }
93	
94	    public void setAddress(String address) {
95	        this.address = address;
96	    }
97	
98	    public String getAddressLine1() {
99	        return this.addressLine1;
100	    }
101	
102	    public void setAddressLine1(String addressLine1) {
103	        this.addressLine1 = addressLine1;
104	    }
105	
106	    public String getAddressLine2() {
107	        return this.addressLine2;
108	    }
109	
110	    public void setAddressLine2(String addressLine2) {
111	        this.addressLine2 = addressLine2;
112	    }
113	
114	    public String getCity() {
115	        return this.city;
116	    }
117	
118	    public void setCity(String city) {
119	        this.city = city;
120	    }
121	
122	    public String getTelephone() {
123	        return this.telephone;
124	    }
125	
126	    public void setTelephone(String telephone) {
127	        this.telephone = telephone;
128	    }
129	
130	    public String getEmail() {
131	        return this.email;
132	    }
133	
134	    public void setEmail(String email) {
135	        this.email = email;
136	    }
137	
138	    public String getPostcode() {
139	        return this.postcode;
140	    }
141	
142	    public void setPostcode(String postcode) {
143	        this.postcode = postcode;
144	    }
145	
146	    public LocalDate getRegistrationDate() {
147	        return this.registrationDate;
148	    }
149	
150	    public void setRegistrationDate(LocalDate registrationDate) {
151	        this.registrationDate = registrationDate;
152	    }
153	
154	    public LocalDate getBirthDate() {
155	        return this.birthDate;
156	    }
157	
158	    public void setBirthDate(LocalDate birthDate) {
159	        this.birthDate = birthDate;
160	    }
161	
162	    public String getCustomerCode() {
163	        return this.customerCode;
164	    }
165	
166	    public void setCustomerCode(String customerCode) {
167	        this.customerCode = customerCode;
168	    }
169	
170	    public Integer getNamesakeCount() {
171	        return this.namesakeCount;
172	    }
173	
174	    public void setNamesakeCount(Integer namesakeCount) {
175	        this.namesakeCount = namesakeCount;
176	    }
177	
178	    public Integer getHouseholdSize() {
179	        return this.householdSize;
180	    }
181	
182	    public void setHouseholdSize(Integer householdSize) {
183	        this.householdSize = householdSize;
184	    }
185	
186	    public Boolean getBulkSignupWarning() {
187	        return this.bulkSignupWarning;
188	    }
189	
190	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
191	        this.bulkSignupWarning = bulkSignupWarning;
192	    }
193	
194	    public Boolean getPossibleDuplicate() {
195	        return this.possibleDuplicate;
196	    }
197	
198	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
199	        this.possibleDuplicate = possibleDuplicate;
200	    }
201	
202	    public Integer getPossibleDuplicateOf() {
203	        return this.possibleDuplicateOf;
204	    }
205	
206	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
207	        this.possibleDuplicateOf = possibleDuplicateOf;
208	    }
209	
210	    protected Set<Pet> getPetsInternal() {
211	        if (this.pets == null) {
212	            this.pets = new HashSet<>();
213	        }
214	        return this.pets;
215	    }
216	
217	    protected void setPetsInternal(Set<Pet> pets) {
218	        this.pets = pets;
219	    }
220	
221	    public List<Pet> getPets() {
222	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
223	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
224	        return Collections.unmodifiableList(sortedPets);
225	    }
226	
227	    public void setPets(List<Pet> pets) {
228	        this.pets = new HashSet<>(pets);
229	    }
230	
231	    public void addPet(Pet pet) {
232	        getPetsInternal().add(pet);
233	        pet.setOwner(this);
234	    }
235	
236	    /**
237	     * Return the Pet with the given name, or null if none found for this Owner.
238	     *
239	     * @param name to test
240	     * @return true if pet name is already in use
241	     */
242	    public Pet getPet(String name) {
243	        return getPet(name, false);
244	    }
245	
246	    /**
247	     * Return the Pet with the given name, or null if none found for this Owner.
248	     *
249	     * @param name to test
250	     * @return true if pet name is already in use
251	     */
252	    public Pet getPet(String name, boolean ignoreNew) {
253	        name = name.toLowerCase();
254	        for (Pet pet : getPetsInternal()) {
255	            if (!ignoreNew || !pet.isNew()) {
256	                String compName = pet.getName();
257	                compName = compName.toLowerCase();
258	                if (compName.equals(name)) {
259	                    return pet;
260	                }
261	            }
262	        }
263	        return null;
264	    }
265	
266	    public Pet getPet(Integer petId) {
267	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
268	    }
269	
270	    @Override
271	    public String toString() {
272	        return new ToStringCreator(this)
273	
274	            .append("id", this.getId())
275	            .append("new", this.isNew())
276	            .append("lastName", this.getLastName())
277	            .append("firstName", this.getFirstName())
278	            .append("address", this.address)
279	            .append("city", this.city)
280	            .append("telephone", this.telephone)
281	            .toString();
282	    }
283	}
